"""P9-5 crypt placement script (Unreal MCP). Reads Docs/plans/p9_d1_layout.json (generated by gen_crypt_layout.py).

Usage (editor open on L_Monastery):
    python place_crypt.py --cats backdrop wall            # place categories (idempotent: removes the category's actors first)
    python place_crypt.py --cats wall --only W_OS         # place only records whose id contains this text (remove only those)
    python place_crypt.py --cats wall --check             # no placing; read back bounds/collision/materials of existing actors
    python place_crypt.py --hide-greybox                  # D-068: StaticMeshComponent.bVisible=false on the greybox shell
    python place_crypt.py --verify-greybox                # read back bVisible/collision and run the trace_world checks

Placed categories (P9-5): backdrop wall pitwall portal vault column ossuary tile stair soffit ceiling grate water.
`dress`, `decal`, `light` are later tasks and are refused here.
Every placed actor: transform set in ONE call (location+rotation+scale), label = id, outliner folder = record folder,
collision (NoCollision records: bUseDefaultCollision=false + bodyInstance.collisionProfileName=NoCollision, both read back;
"BlockAll (mesh hull)" records keep the mesh default), materials per the P9-5 table, then a bounds read-back (tolerance 3 cm).
"""
import argparse
import json
import os
import sys
import time

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "mcp"))
from ue import UE  # noqa: E402

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..")
LAYOUT = os.path.join(ROOT, "Docs", "plans", "p9_d1_layout.json")
S = "editor_toolset.toolsets.scene.SceneTools"
A = "editor_toolset.toolsets.actor.ActorTools"
O = "editor_toolset.toolsets.object.ObjectTools"
MAP = "/Game/LastBell/Maps/L_Monastery.L_Monastery"
MATDIR = "/Game/LastBell/Environments/Crypt/Materials/"
TOL = 3.0

ORDER = ["backdrop", "wall", "pitwall", "portal", "vault", "column", "ossuary", "tile", "stair", "soffit",
         "ceiling", "grate", "water"]
# label prefixes owned by each category (idempotent removal)
PREFIXES = {
    "backdrop": ["CA_Backdrop_"],
    "wall": ["CA_Wall_"],
    "pitwall": ["CA_PitWall_"],
    "portal": ["CA_Portal_"],
    "vault": ["CA_Vault_"],
    "column": ["CA_Pillar_", "CA_Capital_"],
    "ossuary": ["CA_Ossuary_"],
    "tile": ["CA_Tile_"],
    "stair": ["CA_Stair_"],
    "soffit": ["CA_Soffit_", "CA_Lintel_"],
    "ceiling": ["CA_CC_Beam_", "CA_CC_Corbel_", "CA_CC_Boards_", "CA_CC_Soil"],
    "grate": ["CA_CC_Grate", "CA_Grate_", "CA_GrateSky_"],
    "water": ["CA_Water_"],
}
GREYBOX_LABELS = (["Rock_%03d" % i for i in range(17)] + ["CryptFloor_%d" % i for i in range(4)] +
                  ["Pit_Floor", "Pit_W", "Pit_E", "Pit_N", "Pit_S"] + ["Prop_Crypt_%d" % i for i in range(6)] +
                  ["Plinth_Crank"] + ["Stair_SacristyDown_%02d" % i for i in range(40)] +
                  ["Stair_CryptUp_%02d" % i for i in range(40)])
GREYBOX_FOLDERS = ["Crypt", "Crypt/Stairs"]
# trace checks: (name, x, y, start_z, end_z, expected hit z)
TRACES = [("landing (6550,-1100)", 6550, -1100, -100, -700, -600),
          ("flooded ledge (8250,-2450)", 8250, -2450, -100, -700, None),
          ("CC (10750,-900)", 10750, -900, -100, -700, None),
          ("pit-edge ledge (9550,-2388)", 9550, -2388, -100, -700, None),
          ("Sacristy stair step 20 centre", 7415, -1100, -100, -700, -285),
          ("Exit stair step 20 centre", 10650, -85, -150, -700, -285)]


def material_for(rec):
    i, cat = rec["id"], rec["cat"]
    if cat == "backdrop":
        return "MI_Crypt_Backdrop", False
    if cat == "water":
        return rec["mi"], None
    if i == "CA_CC_Soil":
        return "MI_Crypt_Soil", None
    if i in ("CA_CC_GrateSky",) or i.startswith("CA_GrateSky_"):
        return "MI_Crypt_MoonSky", False
    return None, None


class Placer:
    def __init__(self):
        self.ue = UE()

    def call(self, ts, tool, args=None, tries=4):
        for k in range(tries):
            try:
                return self.ue.call(ts, tool, args)
            except Exception as e:  # connection reset etc.
                if k == tries - 1:
                    raise
                print("  retry %s.%s (%s)" % (tool, ts.split(".")[-1], str(e)[:120]))
                time.sleep(2)
                try:
                    self.ue = UE()
                except Exception:
                    time.sleep(3)

    # ---- helpers
    def label(self, a):
        return self.call(A, "get_label", {"actor": a})

    def find_prefix(self, prefix):
        acs = self.call(S, "find_actors", {"name": prefix, "tag": "", "collision_channels": []}) or []
        out = []
        for a in acs:
            if self.label(a).startswith(prefix):
                out.append(a)
        return out

    def remove_category(self, cat, only):
        n = 0
        for p in PREFIXES[cat]:
            for a in self.find_prefix(p):
                lbl = self.label(a)
                if only and only not in lbl:
                    continue
                if cat == "ceiling" and lbl.startswith("CA_CC_Grate"):
                    continue
                self.call(S, "remove_from_scene", {"actor": a})
                n += 1
        return n

    def props(self, comp, names):
        r = self.call(O, "get_properties", {"instance": comp, "properties": names})
        return json.loads(r) if isinstance(r, str) else r

    def set_props(self, comp, values):
        return self.call(O, "set_properties", {"instance": comp, "values": json.dumps(values)})

    def comp0(self, actor):
        comps = self.call(A, "get_components", {"actor": actor})
        return comps[0]

    def bounds(self, actor):
        b = self.call(A, "get_actor_bounds", {"actor": actor})
        return b["min"], b["max"]

    def read_state(self, a, comp, rec, mat_expect):
        p = self.props(comp, ["bUseDefaultCollision", "bodyInstance", "castShadow", "overrideMaterials", "bVisible"])
        prof = p["bodyInstance"]["collisionProfileName"]
        mats = [m["refPath"].split("/")[-1].split(".")[0] if isinstance(m, dict) else str(m) for m in p["overrideMaterials"]]
        return {"profile": prof, "useDefault": p["bUseDefaultCollision"], "castShadow": p["castShadow"], "mats": mats}

    def place_one(self, rec):
        xf = {"location": dict(zip("xyz", rec["loc"])),
              "rotation": {"pitch": rec["rot"][0], "yaw": rec["rot"][1], "roll": rec["rot"][2]},
              "scale": dict(zip("xyz", rec["scale"]))}
        mesh = rec["mesh"]
        asset = mesh if "." in mesh.split("/")[-1] else mesh + "." + mesh.split("/")[-1]
        a = self.call(S, "add_to_scene_from_asset", {"asset_path": asset, "name": rec["id"], "xform": xf})
        if not a:
            raise RuntimeError("spawn failed for " + rec["id"] + " " + asset)
        # one full transform call (never partial)
        self.call(A, "set_actor_transform", {"actor": a, "xform": xf, "worldspace": True})
        self.call(A, "set_label", {"actor": a, "label": rec["id"]})
        self.call(S, "set_actor_folder", {"actor": a, "folder_path": rec["folder"]})
        comp = self.comp0(a)
        vals = {}
        if rec["collision"] == "NoCollision":
            vals["bUseDefaultCollision"] = False
            vals["bodyInstance"] = {"collisionProfileName": "NoCollision"}
        mi, shadow = material_for(rec)
        if mi:
            vals["overrideMaterials"] = [{"refPath": MATDIR + mi + "." + mi}]
        if shadow is False:
            vals["castShadow"] = False
        if vals:
            self.set_props(comp, vals)
        return a, comp

    def verify(self, rec, a, comp):
        """returns (ok, message, state)"""
        mn, mx = self.bounds(a)
        got_min = [mn["x"], mn["y"], mn["z"]]
        got_max = [mx["x"], mx["y"], mx["z"]]
        dev = max(max(abs(g - e) for g, e in zip(got_min, rec["aabb_min"])),
                  max(abs(g - e) for g, e in zip(got_max, rec["aabb_max"])))
        st = self.read_state(a, comp, rec, None)
        ok = dev <= TOL
        issues = []
        if not ok:
            issues.append("bounds dev %.1f" % dev)
        if rec["collision"] == "NoCollision":
            if st["profile"] != "NoCollision" or st["useDefault"]:
                ok = False
                issues.append("collision not NoCollision (%s, useDefault=%s)" % (st["profile"], st["useDefault"]))
        else:
            if st["profile"] == "NoCollision":
                ok = False
                issues.append("expected mesh collision, got NoCollision")
        mi, shadow = material_for(rec)
        if mi and (not st["mats"] or st["mats"][0] != mi):
            ok = False
            issues.append("material %s != %s" % (st["mats"], mi))
        if shadow is False and st["castShadow"]:
            ok = False
            issues.append("castShadow still on")
        return ok, dev, "; ".join(issues), st

    # ---- categories
    def run_cats(self, cats, only, check):
        recs = json.load(open(LAYOUT))["placements"]
        summary = []
        for cat in cats:
            rs = [r for r in recs if r["cat"] == cat and (not only or only in r["id"])]
            removed = 0
            if not check:
                removed = self.remove_category(cat, only)
            print("== %s: %d records (removed %d existing)" % (cat, len(rs), removed), flush=True)
            fails, maxdev = [], 0.0
            for k, r in enumerate(rs):
                if check:
                    found = self.find_prefix(r["id"])
                    found = [f for f in found if self.label(f) == r["id"]]
                    if not found:
                        fails.append((r["id"], "missing"))
                        continue
                    a = found[0]
                    comp = self.comp0(a)
                else:
                    a, comp = self.place_one(r)
                ok, dev, msg, st = self.verify(r, a, comp)
                maxdev = max(maxdev, dev)
                if not ok:
                    fails.append((r["id"], msg))
                    print("  FAIL %s: %s" % (r["id"], msg), flush=True)
                if (k + 1) % 20 == 0:
                    print("  ..%d/%d" % (k + 1, len(rs)), flush=True)
            print("   %s: placed/checked %d, pass %d, fail %d, max bounds deviation %.2f cm" %
                  (cat, len(rs), len(rs) - len(fails), len(fails), maxdev), flush=True)
            summary.append((cat, len(rs), len(rs) - len(fails), len(fails), maxdev))
        print("\nSUMMARY (cat, n, pass, fail, max dev cm)")
        for s in summary:
            print("  %-9s %4d %4d %3d  %.2f" % s)
        return summary

    # ---- greybox
    def greybox_actors(self):
        want = set(GREYBOX_LABELS)
        found = {}
        for fo in GREYBOX_FOLDERS:
            for a in self.call(S, "get_actors_in_folder", {"folder_path": fo, "recursive": False}):
                lbl = self.label(a)
                if lbl in want:
                    found[lbl] = a
        missing = sorted(want - set(found))
        return found, missing

    def hide_greybox(self):
        found, missing = self.greybox_actors()
        print("greybox actors found %d / %d, missing %s" % (len(found), len(GREYBOX_LABELS), missing))
        for lbl, a in found.items():
            comp = self.comp0(a)
            self.set_props(comp, {"bVisible": False})
        self.verify_greybox(found)

    def verify_greybox(self, found=None):
        if found is None:
            found, missing = self.greybox_actors()
            print("greybox actors found %d / %d, missing %s" % (len(found), len(GREYBOX_LABELS), missing))
        bad = 0
        profiles = {}
        for lbl, a in found.items():
            comp = self.comp0(a)
            p = self.props(comp, ["bVisible", "bodyInstance", "bUseDefaultCollision"])
            prof = p["bodyInstance"]["collisionProfileName"]
            profiles[prof] = profiles.get(prof, 0) + 1
            if p["bVisible"] or prof != "BlockAll":
                bad += 1
                print("  BAD", lbl, p["bVisible"], prof)
        print("greybox read-back: %d actors, bVisible true or non-BlockAll: %d, profiles %s" % (len(found), bad, profiles))
        for name, x, y, z0, z1, exp in TRACES:
            d = self.call(S, "trace_world", {"start": {"x": x, "y": y, "z": z0}, "end": {"x": x, "y": y, "z": z1}})
            hit = None if d is None else z0 - d
            print("  trace %-32s distance %s -> hit z %s (expected %s)" % (name, d, hit, exp))


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--cats", nargs="*", default=[])
    ap.add_argument("--only", default="")
    ap.add_argument("--check", action="store_true")
    ap.add_argument("--hide-greybox", action="store_true")
    ap.add_argument("--verify-greybox", action="store_true")
    args = ap.parse_args()
    for c in args.cats:
        if c not in ORDER:
            sys.exit("category %r not allowed in P9-5 (allowed: %s)" % (c, " ".join(ORDER)))
    p = Placer()
    lvl = p.call(S, "get_current_level")
    if not str(lvl).endswith("L_Monastery"):
        sys.exit("editor is not on L_Monastery: %s" % lvl)
    if args.hide_greybox:
        p.hide_greybox()
    if args.verify_greybox:
        p.verify_greybox()
    if args.cats:
        s = p.run_cats(args.cats, args.only, args.check)
        if any(x[3] for x in s):
            sys.exit(2)


if __name__ == "__main__":
    main()
